def params6(d):
    p = dict(d['base'])
    for x in d['lv'][:6]: p.update(x)
    return p


def names(sid):
    out = {}
    for lg in LG:
        S = json.load(open(os.path.join(ROOT, 'work', 'lang_json', f'spells_{lg}.json'), encoding='utf-8'))['S']
        out[lg] = ((S.get(str(sid)) or {}).get('n') or '').strip()
    fr = out['fr']
    return {lg: (v or fr) for lg, v in out.items()}


def apply(C, put_ui):
    put_ui(UI)
    types = {w['id'] for w in C['weapons']}; lst = []
    for fid, (cls, a, b, kind, dsid, icon_n, main, ch, rider, fx2) in F.items():
        A = C['spells'][a]; M = C['spells'][a if main == 'a' else b]
        assert kind != 'weapon' or b in types, b
        assert kind != 'global' or C['spells'][b].get('glob'), b
        d = {k: copy.deepcopy(v) for k, v in M.items() if k not in ('name', 'desc', 'base', 'lv', 'id', 'icon', 'glob', 'evo', 'anim', 'animBy', 'animAll')}
        for k in ('anim', 'animBy', 'animAll'):   # (the class's cast animation, even when the main ingredient is a global spell)
            if k in A: d[k] = copy.deepcopy(A[k])
        base = params6(M); base.update(ch); base.update(rider)
        for k in ('dmg', 'poison', 'burn', 'wallDmg'):   # (every damage number of the spell)
            if isinstance(base.get(k), (int, float)) and not isinstance(base.get(k), bool): base[k] = round(base[k] * CAL.get(fid, 1.0), 2)
        d.update(id=fid, name=names(dsid), desc=DESC[fid], base=base, lv=[], icon=f'sf_{fid}', sfusion=1, cls=cls, src=[a, b], fkind=kind,
                 fx=list(M.get('fx') or []) + ([fx2] if fx2 and fx2 not in (M.get('fx') or []) else []), fx2=fx2)
        C['spells'][fid] = d
        lst.append({'id': fid, 'cls': cls, 'src': [a, b], 'kind': kind})
    C['spellFusions'] = lst
    return lst
